from playwright.sync_api import sync_playwright
from pathlib import Path
import json
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--enable-webgl','--ignore-gpu-blocklist'])
 page=b.new_page(viewport={'width':1100,'height':750}); errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content(Path(__file__).with_name('index.html').read_text(),timeout=15000);page.wait_for_function('window.__thousand?.state.frames > 1');page.screenshot(path=str(Path(__file__).with_name('browser-entry.png'))); start=page.evaluate('window.__thousand.state');page.keyboard.press('w');page.mouse.move(500,300);page.mouse.down();page.mouse.move(550,320);page.mouse.up(); yaw=page.evaluate('window.__thousand.state.yaw');page.wait_for_function("window.__thousand.state.current==='lantern'",timeout=12000);finish=page.evaluate('window.__thousand.state');page.screenshot(path=str(Path(__file__).with_name('browser-lantern.png')));assert abs(finish['yaw']-yaw)<1e-9;assert not errors; assert not page.locator('#err').text_content();result={'status':'pass','mode':start['renderer'],'browser':'Chromium 144 via set_content','start':start,'arrival':finish,'cameraPreserved':True,'errors':errors,'limits':'WebGL2 unavailable in this environment; CPU mode tested, audio not tested; hosted preview not verified'};(Path(__file__).parent/'evidence'/'browser-results.json').write_text(json.dumps(result,indent=2));print(json.dumps(result));b.close()
